/** Apply `f` to the "initial element" of this chain and lazily combine it with every other value using the given function `g`. {{{ scala> import cats.data.NonEmptyChain scala> val nec = NonEmptyChain(4, 5, 6) scala> nec.reduceLeftTo(_.toString)((acc, cur) => acc + cur.toString) res0: String = 456 }}} */
final def reduceLeftTo[B](f: A => B)(g: (B, A) => B): B = {
  val iter = toChain.iterator
  var result = f(iter.next())
  while (iter.hasNext) { result = g(result, iter.next()) }
  result
}
