/** If the type to which the response body should be deserialized is an `Either[ResponseException[HE], B]`, either throws / returns a failed effect with the [[DeserializationException]], returns the deserialized body from the [[UnexpectedStatusCode]], or the deserialized successful body `B`. */
def orFailDeserialization[HE, B](implicit
    tIsEither: T <:< Either[ResponseException[HE], B]
): ResponseAs[Either[HE, B]] = map { t =>
  (t: Either[ResponseException[HE], B]) match {
    case Left(UnexpectedStatusCode(he, _)) => Left(he)
    case Left(d: DeserializationException) => throw d
    case Right(b)                          => Right(b)
  }
}
