  // This is an optimized (unboxed) implementation
  // of the same code as foldLeft
  @annotation.tailrec
  def loop(head: Chain.NonEmpty[A], tail: List[Chain.NonEmpty[A]], len: Long): Int =
    if (len <= 0L) 1 // head is nonempty
