      head match {
        case Append(l, r) => loop(l, r :: tail, len)
        case Singleton(_) =>
          tail match {
            case h1 :: t1 =>
              loop(h1, t1, len - 1L)
            case _ =>
              java.lang.Long.compare(1L, len)
