      var c: Chain.NonEmpty[A] = non
      // a stack of rights
      var rights: List[Chain.NonEmpty[A]] = Nil

      while (c ne null) {
        c match {
          case Singleton(a) =>
            val b = f(a)
            if (b) return ()
            c =
              if (rights.isEmpty) null
              else {
                val head = rights.head
                rights = rights.tail
                head
              }
          case Append(l, r) =>
            rights = r :: rights
            c = l
          case Wrap(seq) =>
            val iterator = seq.iterator
            while (iterator.hasNext) {
              val b = f(iterator.next())
              if (b) return ()
            }
            c =
              if (rights.isEmpty) null
              else {
                val head = rights.head
                rights = rights.tail
                head
              }
        }
      }
    case _ => ()
  }
