/** Removes duplicate elements from a list, keeping only the first occurrence. This is usually faster than ordDistinct, especially for things that have a slow comparison (like String). */
def hashDistinct[A](fa: F[A])(implicit H: Hash[A]): F[A] =
  traverseFilter(fa) { a =>
    State { (distinct: IntMap[List[A]]) =>
      val ahash = H.hash(a)
      distinct.get(ahash) match {
        case None           => (distinct.updated(ahash, a :: Nil), Some(a))
        case Some(existing) =>
          if (Traverse[List].contains_(existing, a))
            (distinct, None)
          else
            (distinct.updated(ahash, a :: existing), Some(a))
      }
    }
  }
