final def fromIterable(fields: Iterable[(String, Json)]): JsonObject = {
  if (fields.isEmpty) {
    empty
  } else {
    val map = new LinkedHashMap[String, Json]
    val iterator = fields.iterator

    while (iterator.hasNext) {
      val (key, value) = iterator.next()

      map.put(key, value)
    }

    fromLinkedHashMap(map)
  }
}
