/** Returns a new `Order[A]` instance that first compares by the first `Order` instance and uses the second `Order` instance to "break ties". That is, `Order.whenEqual(x, y)` creates an `Order` that first orders by `x` and then (if two elements are equal) falls back to `y` for the comparison. */
def whenEqual[@sp A](first: Order[A], second: Order[A]): Order[A] = { (x, y) =>
  val c = first.compare(x, y)
  if (c == 0) second.compare(x, y)
  else c
}
