/** Gen JS code for an Apply node (method call) There's a whole bunch of varieties of Apply nodes: regular method calls, super calls, constructor calls, isInstanceOf/asInstanceOf, primitives, JS calls, etc. They are further dispatched in here. */
def genApply(tree: Apply, isStat: Boolean): js.Tree = {
  implicit val pos = tree.pos
  val Apply(fun, args) = tree

  fun match {
    case TypeApply(_, _) =>
      genApplyTypeApply(tree)

    case Select(Super(_, _), _) =>
      genSuperCall(tree)

    case Select(New(_), nme.CONSTRUCTOR) =>
      genApplyNew(tree)

    case _ =>
      val sym = fun.symbol

      if (sym.isLabel) {
        genLabelApply(tree)
      } else if (scalaPrimitives.isPrimitive(sym)) {
        genPrimitiveOp(tree, isStat)
      } else if (currentRun.runDefinitions.isBox(sym)) {
        // Box a primitive value (cannot be Unit)
        val arg = args.head
        makePrimitiveBox(genExpr(arg), arg.tpe)
      } else if (currentRun.runDefinitions.isUnbox(sym)) {
        // Unbox a primitive value (cannot be Unit)
        val arg = args.head
        makePrimitiveUnbox(genExpr(arg), tree.tpe)
      } else {
        genNormalApply(tree, isStat)
      }
  }
}
