final def runM[M[_]](f: S[Free[S, A]] => M[Free[S, A]])(implicit S: Functor[S], M: Monad[M]): M[A] = {
  def step(t: S[Free[S, A]]): M[Either[S[Free[S, A]], A]] =
    M.map(f(t))(_.resume)

  resume match {
    case Left(s)  => M.tailRecM(s)(step)
    case Right(r) => M.pure(r)
  }
}
