def orFail[A, B](implicit tIsEither: T <:< Either[A, B]): WebSocketStreamResponseAs[B, S] =
  mapWithMetadata { case (t, meta) =>
    (t: Either[A, B]) match {
      case Left(a: Exception) => throw a
      case Left(a)            => throw UnexpectedStatusCode(a, meta)
      case Right(b)           => b
    }
  }
