final def resume(implicit S: Functor[S]): Either[S[Free[S, A]], A] =
  this match {
    case Pure(a)          => Right(a)
    case Suspend(t)       => Left(S.map(t)(Pure(_)))
    case FlatMapped(c, f) =>
      c match {
        case Pure(a)          => f(a).resume
        case Suspend(t)       => Left(S.map(t)(f))
        case FlatMapped(d, g) => d.flatMap(dd => g(dd).flatMap(f)).resume
      }
  }
```

