def reverse: Chain[A] = {
  @annotation.tailrec
  def loop[B <: A](h: Chain.NonEmpty[B], tail: List[Chain.NonEmpty[B]], acc: Chain[A]): Chain[A] =
    h match {
      case Append(l, r)        => loop(l, r :: tail, acc)
      case sing @ Singleton(_) =>
        val nextAcc = sing.concat(acc)
        tail match {
          case h1 :: t1 =>
            loop(h1, t1, nextAcc)
          case _ =>
            nextAcc
        }
      case Wrap(seq) =>
        val nextAcc = Wrap(seq.reverse).concat(acc)
        tail match {
          case h1 :: t1 =>
            loop(h1, t1, nextAcc)
          case _ =>
            nextAcc
        }
    }

  this match {
    case Append(l, r) =>
      loop(l, r :: Nil, Empty)
    case Wrap(seq) => Wrap(seq.reverse)
    case _         =>
      // Empty | Singleton(_)
      this
  }
}
```

