/** Perform a deep merge of this JSON object with another JSON object. Objects are merged by key, values from the argument JSON take precedence over values from this JSON. Nested objects are recursed. See [[Json.deepMerge]] for behavior of merging values that are not objects. */
def deepMerge(that: JsonObject): JsonObject =
  toIterable.foldLeft(that) {
    case (acc, (key, value)) =>
      that(key).fold(acc.add(key, value)) { r =>
        acc.add(key, value.deepMerge(r))
      }
  }
