/** Is a string representing an integral value a valid [[scala.Long]]? Note that this method assumes that the input is a valid integral JSON number string (e.g. that it does have leading zeros). */
def integralIsValidLong(s: String): Boolean = {
  val bound = if (s.charAt(0) == '-') MinLongString else MaxLongString

  s.length < bound.length || (s.length == bound.length && s.compareTo(bound) <= 0)
}
