def anyEqualSemilattice[A]: Semilattice[Eq[A]] =
  new Semilattice[Eq[A]] {
    def combine(e1: Eq[A], e2: Eq[A]): Eq[A] = Eq.or(e1, e2)
    override def combineAllOption(es: IterableOnce[Eq[A]]): Option[Eq[A]] =
