final def deleteFirst(f: A => Boolean): Option[(A, Chain[A])] = {
  @tailrec
  def go(rem: Chain[A], acc: Chain[A]): Option[(A, Chain[A])] =
    rem.uncons match {
      case Some((a, tail)) =>
        if (!f(a)) go(tail, acc :+ a)
        else Some((a, acc ++ tail))

      case None => None
    }
  go(this, Chain.nil)
}
