/** Normalizes an index by triggering index reset if needed. Call this periodically (e.g., after processing each element) to prevent index overflow when parsing files >2GB. */
def normalizeIndex(i: Int): Int = {
  if (firstIdx > IndexResetThreshold) {
    // Trigger a reset: shift all indices down by firstIdx
    val shift = firstIdx
    droppedOffset += shift
    lastIdx -= shift
    dropped -= shift
    if (knownEof != Int.MaxValue) {
      knownEof -= shift
    }
    firstIdx = 0
    i - shift
  } else {
    i
  }
}
