final def findAllByKey(key: String): List[Json] = {
  val hh: ListBuffer[Json] = ListBuffer.empty[Json]
  def loop(json: Json): Unit = json match {
    case JObject(obj) =>
      obj.toIterable.foreach {
        case (k, v) =>
          if (k == key) hh += v
          loop(v)
      }
    case JArray(elems) => elems.foreach(loop)
    case _             => // do nothing
  }
  loop(this)
  hh.toList
}
