  if (idx < 0L)
    None
  else
    mapAccumulate(0L, fa)((i, a) =>
      if (i == idx)
        (i + 1, b)
      else
        (i + 1, a)
    ) match {
      case (i, fb) if i > idx => Some(fb)
      case _                  => None
    }
}
