      case Success(a) => Right(a)
      case Failure(t) =>
        Left(
          DecodingFailure(
            s"Couldn't decode value '$str'. " +
              s"Allowed values: '${enumeration.values.mkString(",")}'",
            c.history
          )
        )
    }
  }
  final def apply(e: E#Value): Json = Encoder.encodeString(e.toString)
}
