final def runTailRec(implicit S: Monad[S]): S[A] = {
  def step(rma: Free[S, A]): S[Either[Free[S, A], A]] =
    rma match {
      case Pure(a) =>
        S.pure(Right(a))
      case Suspend(ma) =>
        S.map(ma)(Right(_))
      case FlatMapped(curr, f) =>
        curr match {
          case Pure(x) =>
            S.pure(Left(f(x)))
          case Suspend(mx) =>
            S.map(mx)(x => Left(f(x)))
          case FlatMapped(prev, g) =>
            S.pure(Left(prev.flatMap(w => g(w).flatMap(f))))
        }
    }
  S.tailRecM(this)(step)
}
```

