/** Separate the inner foldable values into the "lefts" and "rights". Example: {{{ scala> val l: List[Either[String, Int]] = List(Right(1), Left("error")) scala> Alternative[List].separate(l) res0: (List[String], List[Int]) = (List(error),List(1)) }}} */
def separate[G[_, _], A, B](fgab: F[G[A, B]])(implicit FM: FlatMap[F], G: Bifoldable[G]): (F[A], F[B]) = {
  val as = FM.flatMap(fgab)(gab => G.bifoldMap(gab)(pure, _ => empty[A])(using algebra[A]))
